// import 
import '../../../styles/acco.css';
import Dform from './Dform';
import Headimg from './Headimg';
import Mainh from './Mainh';
import Sidebar from './Sidebar';
import Ylocations from './Ylocations';
import Dogimage from '../../../assests/images/dogs_image_no_text.jpg';
import Yaccopage1 from './Yaccopage1';


//function 
const Ypage1 = () =>{
    return (
        <div>
            <Headimg logo = {Dogimage} title = "Volunteer" dec = "Give a lovely gift"/> 
            <Sidebar />
            <Mainh />
            <div className = "accordion-container">
                <Yaccopage1 title1 = "Secondhand Items" dec1={`<strong>We will happily accept your second-hand pet items. We ask that any used items are cleaned prior to donating. Rafeeq can accept:</strong>
        <ul>
          <li>Unopened and unexpired food and treats</li>
          <li>Blankets, Towels, Sheets</li>
          <li>Leashes and Harnesses</li>
          <li>Crates and Carriers</li>
          <li>Enrichment Toys</li>
          <li>Unopened Litter, Pellets</li>
        </ul>
        <strong>Our care centers accept donations daily between 10AM and 5PM.<br>
        Please note we cannot accept open/expired food and treats, medications, pillows or mattresses.</strong>`}
      />
                <Yaccopage1 title1 = "dfgdfg" dec1 = "dfgdfg"/>
                <Yaccopage1 title1 = "hdfgdf" dec1 = "gdfhgdfg"/>
            </div>
            <Ylocations  loc1 = "Nablus" loc2 = "Jenin" loc3 = "Tulkarm"/>
            <Dform />
           

        </div>

    )
}

//export 
export default Ypage1
